import { DatabaseSync } from 'node:sqlite';
function main(): void {
  const db = new DatabaseSync(':memory:');
  db.exec('CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT, score REAL)');
  const insert = db.prepare('INSERT INTO users (name, score) VALUES (?, ?)');
  insert.run('ada', 9.5);
  insert.run('grace', 7);
  const rows: any[] = db.prepare('SELECT id, name, score FROM users ORDER BY id').all();
  for (const row of rows) console.log(row.id, row.name, row.score, typeof row.score);
  console.log(rows.length, Object.getPrototypeOf(rows[0]) === null);
  db.close();
}
